// Private Alexa skill endpoint for Athan Hub, deployed as a Vercel function next to the
// athan audio. It streams a full-length athan with Alexa's AudioPlayer, which, unlike
// the SSML <audio> tag Home Assistant uses, has no 240-second limit.
//
// _manifest.js is generated by athan-audio-sync: { skillId, general: [url], fajr: [url] }.
const manifest = require("./_manifest");

const pick = (list) => list[Math.floor(Math.random() * list.length)];

function speak(text, end = true) {
  return { version: "1.0", response: { outputSpeech: { type: "PlainText", text }, shouldEndSession: end } };
}

function play(url, offset = 0) {
  return {
    version: "1.0",
    response: {
      directives: [{
        type: "AudioPlayer.Play",
        playBehavior: "REPLACE_ALL",
        audioItem: { stream: { url, token: url, offsetInMilliseconds: offset } },
      }],
      shouldEndSession: true,
    },
  };
}

function stop() {
  return { version: "1.0", response: { directives: [{ type: "AudioPlayer.Stop" }], shouldEndSession: true } };
}

function choose(slotValue) {
  const wantsFajr = /fajr|fajir|dawn|morning/i.test(slotValue || "");
  const list = wantsFajr && manifest.fajr.length ? manifest.fajr : manifest.general;
  return list.length ? pick(list) : null;
}

module.exports = (req, res) => {
  if (req.method !== "POST") {
    res.status(405).send("Alexa skill endpoint");
    return;
  }
  const body = req.body || {};
  const applicationId =
    body.session?.application?.applicationId || body.context?.System?.application?.applicationId;
  if (!manifest.skillId || applicationId !== manifest.skillId) {
    res.status(403).json({ error: "unknown skill" });
    return;
  }
  const request = body.request || {};
  const type = request.type || "";
  let reply;
  if (type === "LaunchRequest") {
    const url = choose("");
    reply = url ? play(url) : speak("There is no athan uploaded yet.");
  } else if (type === "IntentRequest") {
    const intent = request.intent?.name;
    if (intent === "PlayAthanIntent") {
      const url = choose(request.intent.slots?.prayer?.value);
      reply = url ? play(url) : speak("There is no athan uploaded yet.");
    } else if (intent === "AMAZON.ResumeIntent") {
      const token = body.context?.AudioPlayer?.token;
      reply = token ? play(token, body.context.AudioPlayer.offsetInMilliseconds || 0) : speak("Nothing to resume.");
    } else if (["AMAZON.PauseIntent", "AMAZON.StopIntent", "AMAZON.CancelIntent"].includes(intent)) {
      reply = stop();
    } else if (intent === "AMAZON.HelpIntent") {
      reply = speak("Say, ask Athan Hub to play the athan, or to play the Fajr athan.", false);
    } else {
      reply = speak("Sorry, Athan Hub can only play the athan.");
    }
  } else {
    // AudioPlayer and PlaybackController events, SessionEndedRequest: acknowledge only.
    reply = { version: "1.0", response: {} };
  }
  res.status(200).json(reply);
};
